pub fn keyed_apply_patch<K: Clone, V: Clone>(rows: Rc<Vec<Rc<KeyedRow<K, V>>>>, patch: Rc<KeyedPatch<K, V>>, key_eq: impl Fn(K, K) -> bool + Clone) -> Rc<Vec<Rc<KeyedRow<K, V>>>> {
    patch.hunks.clone().iter().cloned().fold(rows.clone(), |acc: Rc<Vec<Rc<KeyedRow<K, V>>>>, hunk: Rc<KeyedDiffHunk<K, V>>| match (*hunk.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { hunk_key: k, to: v, .. } => v1_rt::concat(Rc::new({ let mut __result = Vec::new(); for row in acc.iter().cloned() { if !key_eq(row.row_key.clone(), k.clone()) { __result.push(row); } } __result }), Rc::new(vec![Rc::new(KeyedRow {
    row_key: k.clone(),
    value: v.clone(),
    _phantom: std::marker::PhantomData,
})])),
    KeyedDiffHunk::KeyedDiffRemovedHunk { hunk_key: k, .. } => Rc::new({ let mut __result = Vec::new(); for row in acc.iter().cloned() { if !key_eq(row.row_key.clone(), k.clone()) { __result.push(row); } } __result }),
    KeyedDiffHunk::KeyedDiffModifiedHunk { hunk_key: k, to: v, .. } => match crate::std_keyed_row::keyed_row_find(acc.clone(), k.clone(), key_eq.clone()) {
    Some(row) => v1_rt::concat(Rc::new({ let mut __result = Vec::new(); for candidate in acc.iter().cloned() { if !key_eq(candidate.row_key.clone(), k.clone()) { __result.push(candidate); } } __result }), Rc::new(vec![keyed_apply_row(row.clone(), hunk.clone())])),
    std::option::Option::None => acc.clone(),
},
})
}

pub fn keyed_invert_hunk<K: Clone, V: Clone>(hunk: Rc<KeyedDiffHunk<K, V>>) -> Rc<KeyedDiffHunk<K, V>> {
    match (*hunk.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { hunk_key: k, to: v, .. } => Rc::new(KeyedDiffHunk::KeyedDiffRemovedHunk {
    hunk_key: k.clone(),
    from: v.clone(),
}),
    KeyedDiffHunk::KeyedDiffRemovedHunk { hunk_key: k, from: v, .. } => Rc::new(KeyedDiffHunk::KeyedDiffAddedHunk {
    hunk_key: k.clone(),
    to: v.clone(),
}),
    KeyedDiffHunk::KeyedDiffModifiedHunk { hunk_key: k, from: f, to: t, .. } => Rc::new(KeyedDiffHunk::KeyedDiffModifiedHunk {
    hunk_key: k.clone(),
    from: t.clone(),
    to: f.clone(),
}),
}
}

pub fn keyed_invert_patch<K: Clone, V: Clone>(patch: Rc<KeyedPatch<K, V>>) -> Rc<KeyedPatch<K, V>> {
    Rc::new(KeyedPatch {
    hunks: Rc::new({ let mut __result = Vec::new(); for hunk in patch.hunks.clone().iter().cloned() { __result.push(keyed_invert_hunk(hunk.clone())); } __result }),
    _phantom: std::marker::PhantomData,
})
}

pub fn keyed_patch_hunk_count<K: Clone, V: Clone>(patch: Rc<KeyedPatch<K, V>>) -> i64 {
    crate::std_algebra::length(patch.hunks.clone())
}

pub fn keyed_three_way_entry_count<K: Clone, V: Clone>(patch: Rc<KeyedThreeWayPatch<K, V>>) -> i64 {
    crate::std_algebra::length(patch.entries.clone())
}

pub fn keyed_diff_hunks_equal<K: Clone, V: Clone>(left: Rc<KeyedDiffHunk<K, V>>, right: Rc<KeyedDiffHunk<K, V>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> bool {
    match (*left.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { hunk_key: lk, to: lv, .. } => match (*right.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { hunk_key: rk, to: rv, .. } => (key_eq(lk.clone(), rk.clone()) && value_eq(lv.clone(), rv.clone())),
    KeyedDiffHunk::KeyedDiffRemovedHunk { .. } => false,
    KeyedDiffHunk::KeyedDiffModifiedHunk { .. } => false,
},
    KeyedDiffHunk::KeyedDiffRemovedHunk { hunk_key: lk, from: lv, .. } => match (*right.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { .. } => false,
    KeyedDiffHunk::KeyedDiffRemovedHunk { hunk_key: rk, from: rv, .. } => (key_eq(lk.clone(), rk.clone()) && value_eq(lv.clone(), rv.clone())),
    KeyedDiffHunk::KeyedDiffModifiedHunk { .. } => false,
},
    KeyedDiffHunk::KeyedDiffModifiedHunk { hunk_key: lk, from: lf, to: lt, .. } => match (*right.clone()).clone() {
    KeyedDiffHunk::KeyedDiffAddedHunk { .. } => false,
    KeyedDiffHunk::KeyedDiffRemovedHunk { .. } => false,
    KeyedDiffHunk::KeyedDiffModifiedHunk { hunk_key: rk, from: rf, to: rt, .. } => ((key_eq(lk.clone(), rk.clone()) && value_eq(lf.clone(), rf.clone())) && value_eq(lt.clone(), rt.clone())),
},
}
}

pub fn keyed_patch_contains_hunk<K: Clone, V: Clone>(patch: Rc<KeyedPatch<K, V>>, hunk: Rc<KeyedDiffHunk<K, V>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> bool {
    patch.hunks.clone().iter().cloned().fold(false, |acc: bool, candidate: Rc<KeyedDiffHunk<K, V>>| (acc || keyed_diff_hunks_equal(candidate.clone(), hunk.clone(), key_eq.clone(), value_eq.clone())))
}

pub fn keyed_patches_equal<K: Clone, V: Clone>(left: Rc<KeyedPatch<K, V>>, right: Rc<KeyedPatch<K, V>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> bool {
    ((crate::std_algebra::length(left.hunks.clone()) == crate::std_algebra::length(right.hunks.clone())) && left.hunks.clone().iter().cloned().fold(true, |ok: bool, hunk: Rc<KeyedDiffHunk<K, V>>| (ok && keyed_patch_contains_hunk(right.clone(), hunk.clone(), key_eq.clone(), value_eq.clone()))))
}

pub fn keyed_rows_snapshot_equal<K: Clone, V: Clone>(left: Rc<Vec<Rc<KeyedRow<K, V>>>>, right: Rc<Vec<Rc<KeyedRow<K, V>>>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> bool {
    {
        let keys = keyed_union_keys(left.clone(), right.clone(), key_eq.clone());
keys.iter().cloned().fold(true, |ok: bool, wanted_key: _| match crate::std_keyed_row::keyed_row_find(left.clone(), wanted_key.clone(), key_eq.clone()) {
    Some(lr) => match crate::std_keyed_row::keyed_row_find(right.clone(), wanted_key.clone(), key_eq.clone()) {
    Some(rr) => (ok.clone() && value_eq(lr.value.clone(), rr.value.clone())),
    std::option::Option::None => false,
},
    std::option::Option::None => match crate::std_keyed_row::keyed_row_find(right.clone(), wanted_key.clone(), key_eq.clone()) {
    Some(_) => false,
    std::option::Option::None => ok.clone(),
},
})
}
}

pub fn keyed_apply_two_way_diff<K: Clone + 'static, V: Clone + 'static>(left: Rc<Vec<Rc<KeyedRow<K, V>>>>, right: Rc<Vec<Rc<KeyedRow<K, V>>>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> Rc<Vec<Rc<KeyedRow<K, V>>>> {
    keyed_apply_patch(left.clone(), keyed_two_way_diff(left.clone(), right, key_eq.clone(), value_eq), key_eq.clone())
}

pub fn keyed_retract_two_way_diff<K: Clone + 'static, V: Clone + 'static>(left: Rc<Vec<Rc<KeyedRow<K, V>>>>, right: Rc<Vec<Rc<KeyedRow<K, V>>>>, key_eq: impl Fn(K, K) -> bool + Clone, value_eq: impl Fn(V, V) -> bool + Clone) -> Rc<Vec<Rc<KeyedRow<K, V>>>> {
    keyed_apply_patch(right.clone(), keyed_invert_patch(keyed_two_way_diff(left, right.clone(), key_eq.clone(), value_eq)), key_eq.clone())
}
